div.script:
(function () {
    var raw = document.getElementById('ccr_batch_map');
    var MAP = {};
    try { MAP = JSON.parse(raw ? raw.textContent : '{}'); }
    catch (e) { MAP = {}; }
    var sel = document.getElementById('ccr_course');
    var bs = document.getElementById('ccr_batch');
    if (!sel || !bs) { return; }
    function fill(keep) {
        var list = MAP[String(sel.value)] || [];
        bs.innerHTML = '';
        if (!list.length) {
            var o0 = document.createElement('option');
            o0.value = '';
            o0.textContent = '该课程下暂无可选班级';
            bs.appendChild(o0);
            return;
        }
        var ph = document.createElement('option');
        ph.value = '';
        ph.textContent = '请选择班级';
        bs.appendChild(ph);
        list.forEach(function (b) {
            var o = document.createElement('option');
            o.value = String(b.id);
            o.textContent = b.name + '（在读 ' + b.student_n + ' 人 · 课节 ' + b.session_n + '）';
            if (keep === String(b.id)) { o.selected = true; }
            bs.appendChild(o);
        });
    }
    sel.addEventListener('change', function () { fill(''); });
    fill('');
})();
